-- >>> migrations/20261123000400_api_grants.sql
-- Explicit API grants.
-- Newer Supabase projects no longer give the API roles (anon, authenticated,
-- service_role) automatic access to new tables, so the website got
-- "permission denied" (42501). Row Level Security still decides which rows
-- each role can see or change; these grants only open the door to the table.
-- Safe to run more than once.

grant usage on schema public to anon, authenticated, service_role;

-- Tables: RLS is enabled on every table in public (see auth_and_security).
grant select, insert, update, delete on all tables in schema public to anon, authenticated, service_role;

-- Sequences: only the server (e.g. ai_usage_log ids). student_code_seq stays
-- closed to anon/authenticated; enroll_student uses it as owner.
grant usage, select on all sequences in schema public to service_role;

-- Helper functions used inside RLS policies run as the caller, so every API
-- role needs EXECUTE on them.
grant execute on function
  public.current_user_role(),
  public.is_admin(),
  public.is_staff(),
  public.teaches_subject(uuid),
  public.teaches_lesson(uuid),
  public.student_can_see_subject(uuid),
  public.has_paid_service(uuid, public.paid_service),
  public.setting_int(text, integer),
  public.lesson_is_unlocked(uuid)
to anon, authenticated, service_role;

-- Student actions (anon stays revoked).
grant execute on function public.enroll_student(text, smallint, public.version_code, public.group_code) to authenticated, service_role;
grant execute on function public.record_lesson_progress(uuid, integer) to authenticated, service_role;
grant execute on function public.subject_lessons(uuid) to authenticated, service_role;


-- >>> migrations/20261124000100_lesson_admin.sql
-- =============================================================================
-- D2 - Admin "Video Upload": move a lesson up or down in its subject's list.
-- Runs as the caller, so the normal lesson update policy (subject staff)
-- still decides who may do it. The (subject_id, sequence) unique constraint
-- is deferrable, which lets two lessons swap places in one step.
-- =============================================================================

create or replace function public.move_lesson(p_lesson_id uuid, p_direction integer)
returns void
language plpgsql security invoker set search_path = '' as $$
declare
  v_subject   uuid;
  v_sequence  integer;
  v_other     uuid;
  v_other_seq integer;
begin
  select l.subject_id, l.sequence into v_subject, v_sequence
  from public.lessons l where l.id = p_lesson_id;
  if not found then
    raise exception 'lesson not found' using errcode = 'P0002';
  end if;

  if p_direction < 0 then
    select l.id, l.sequence into v_other, v_other_seq from public.lessons l
    where l.subject_id = v_subject and l.sequence < v_sequence
    order by l.sequence desc limit 1;
  else
    select l.id, l.sequence into v_other, v_other_seq from public.lessons l
    where l.subject_id = v_subject and l.sequence > v_sequence
    order by l.sequence asc limit 1;
  end if;
  if v_other is null then
    return;  -- already first or last
  end if;

  set constraints all deferred;
  update public.lessons set sequence = v_other_seq where id = p_lesson_id;
  if not found then
    raise exception 'not allowed to change this lesson' using errcode = '42501';
  end if;
  update public.lessons set sequence = v_sequence where id = v_other;
end $$;

revoke all on function public.move_lesson(uuid, integer) from public, anon;
grant execute on function public.move_lesson(uuid, integer) to authenticated, service_role;


